<?php
require_once __DIR__ . '/../config/session.php';
require_once __DIR__ . '/../lib/mouse-lp-store-service.php';
header('Content-Type: application/json'); header('Cache-Control: no-store');
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') !== 'GET') { http_response_code(405); header('Allow: GET'); echo json_encode(['success'=>false,'error'=>'method_not_allowed']); exit; }
$limit=max(1,min(100,(int)($_GET['limit']??20))); $offset=max(0,(int)($_GET['offset']??0));
/** A /useitem request has no receipt foreign key; return same-user/item evidence without claiming delivery. */
function lab_store_history_fulfilment(PDO $pdo,array $p): array { $q=$pdo->prepare('SELECT request_id,status,created_at FROM tbl_item_usage_requests WHERE user_id=? AND item_id=? AND created_at>=? ORDER BY created_at ASC,request_id ASC LIMIT 1'); $q->execute([(string)$p['purchaser_user_id'],(int)$p['source_item_id'],(string)$p['completed_at']]); $r=$q->fetch(PDO::FETCH_ASSOC)?:null; if($r){$s=strtolower(trim((string)$r['status']));$m=['pending'=>['pending_manual_review','Pending manual review'],'approved'=>['pending','Pending'],'denied'=>['failed_cancelled','Failed/Cancelled'],'cancelled'=>['failed_cancelled','Failed/Cancelled'],'rejected'=>['failed_cancelled','Failed/Cancelled']];if(isset($m[$s]))return['fulfilment_status'=>$m[$s][0],'fulfilment_label'=>$m[$s][1],'fulfilment_evidence'=>'same_user_item_request_after_receipt','request'=>['request_id'=>(int)$r['request_id'],'status'=>$s,'created_at'=>(string)$r['created_at']]];}if((string)$p['receipt_source']==='mouse_lp_store'){ $ref=(int)($p['delivery_reference_id']??0);$normal=(string)$p['source_type']==='normal_store';if($ref>0){$t=$normal?'tbl_user_inventory':'tbl_user_genetic_items';$i=$normal?'inventory_id':'genetic_item_id';$d=$pdo->prepare("SELECT 1 FROM {$t} WHERE {$i}=? AND user_id=? LIMIT 1");$d->execute([$ref,(string)$p['purchaser_user_id']]);if((bool)$d->fetchColumn())return['fulfilment_status'=>'delivered','fulfilment_label'=>'Delivered','fulfilment_evidence'=>'delivery_reference','request'=>null];}}return['fulfilment_status'=>'status_unavailable','fulfilment_label'=>'Status unavailable','fulfilment_evidence'=>'no_receipt_linked_delivery_state','request'=>null]; }
try{$pdo=getDatabaseConnection();// Only this receipt table is created by the Lab Store offer flow for both LP and DSPOINC. tbl_purchase_history has no offer/source linkage and is deliberately excluded.
 $rows="WITH receipt_rows AS (SELECT 'mouse_lp_store' receipt_source,purchase_id receipt_id,purchaser_user_id,source_type,source_item_id,item_title_snapshot,payment_method,amount_paid,delivery_reference_id,completed_at FROM tbl_mouse_lp_store_purchases)";$c=$pdo->query($rows.' SELECT COUNT(*) FROM receipt_rows');$total=(int)$c->fetchColumn();$s=$pdo->prepare($rows.' SELECT * FROM receipt_rows ORDER BY completed_at DESC,receipt_source DESC,receipt_id DESC LIMIT ? OFFSET ?');$s->bindValue(1,$limit,PDO::PARAM_INT);$s->bindValue(2,$offset,PDO::PARAM_INT);$s->execute();$purchases=[];foreach($s->fetchAll(PDO::FETCH_ASSOC) as $r){$fulfilment=lab_store_history_fulfilment($pdo,$r);unset($r['purchaser_user_id']);$purchases[]=array_merge(['receipt'=>['source'=>(string)$r['receipt_source'],'id'=>(int)$r['receipt_id'],'display_id'=>(string)$r['receipt_source'].':'.(int)$r['receipt_id']]],$r,$fulfilment);}echo json_encode(['success'=>true,'purchases'=>$purchases,'pagination'=>['limit'=>$limit,'offset'=>$offset,'total'=>$total,'has_more'=>$offset+$limit<$total]]);}catch(Throwable $e){error_log('Lab Store history: '.$e->getMessage());http_response_code(503);echo json_encode(['success'=>false,'error'=>'history_unavailable']);}